-- Contract checks for the OpenAPI support-readable allow-list.
\set ON_ERROR_STOP 1
DO $$
DECLARE
    v_enabled integer;
    v_column_type text;
BEGIN
    SELECT data_type INTO v_column_type
      FROM information_schema.columns
     WHERE table_schema = 'ref'
       AND table_name = 'action_catalog'
       AND column_name = 'support_readable';
    IF v_column_type IS DISTINCT FROM 'boolean' THEN
        RAISE EXCEPTION 'SUPPORT_READABLE_COLUMN_MISSING_OR_WRONG_TYPE';
    END IF;
    SELECT count(*) INTO v_enabled
      FROM ref.action_catalog
     WHERE support_readable IS TRUE;
    IF v_enabled <> 124 THEN
        RAISE EXCEPTION 'SUPPORT_READABLE_SEED_COUNT_MISMATCH: expected 124, found %', v_enabled;
    END IF;
    IF EXISTS (
        SELECT 1 FROM ref.action_catalog
         WHERE action_code IN ('ACCREDITATION_EVIDENCE_MAP','APPROVAL_DELEGATE','ASSIGNMENT_CREATE','ASSIGNMENT_VIEW_OWN','ATTENDANCE_BULK_UPLOAD','ATTENDANCE_BULK_UPLOAD_APPROVE','ATTENDANCE_CORRECTION_APPROVE','ATTENDANCE_VIEW','ATTENDANCE_VIEW_OWN','AUDIT_FINDING_RECORD','AUDIT_LOG_EXPORT','AUDIT_LOG_VIEW','BACKUP_STATUS_VIEW','BULK_CORRECT','BUYER_DASHBOARD_VIEW','CALENDAR_LOCAL_SET','CALENDAR_MASTER_SET','CERTIFICATE_APPROVE','COMMUNITY_LIKE_COMMENT','COMMUNITY_POST_APPROVE','COMMUNITY_POST_DIRECT','COMMUNITY_POST_SUBMIT','COMPLIANCE_REPORT_MANAGE','CONCESSION_APPROVE','DATA_IMPORT','DELIVERY_FAILURES_VIEW','DEPT_DOCUMENT_UPLOAD','EVENT_APPROVE','EVENT_PROPOSE','EVENT_RSVP','EXAM_PATTERN_SET','EXAM_RULES_SET','EXAM_SCHEDULE_APPROVE','EXAM_SCHEDULE_INTERNAL','EXAM_SCHEDULE_UNIVERSITY','EXAM_SCHEDULE_VIEW_OWN','EXAM_VIEW','FEE_EXCEPTION_APPROVE_FIRST','FEE_EXCEPTION_APPROVE_PRINCIPAL','FEE_POLICY_DATA_ENTER','FEE_POLICY_SET','FEE_REMINDER_SEND','FEE_STRUCTURE_APPROVE','FEE_STRUCTURE_CREATE','GOVERNANCE_ITEM_APPROVE','GRADING_SCHEME_SET','GUARDIAN_CHANGE_APPROVE','HALL_TICKET_GENERATE','HOMEWORK_COMPLIANCE_VIEW','ID_CARD_EXPORT','INSTITUTION_ACTIVATE','INSTITUTION_BLOCK_APPROVE','INTEGRATION_SETTINGS_VIEW','LATE_FEE_RULES_SET','LATE_FEE_WAIVER_APPROVE','LEAVE_BALANCE_CREDIT','LEAVE_TYPES_SET','LEDGER_VIEW','MARKS_APPROVE_HOD','MARKS_APPROVE_PRINCIPAL','MARKS_EXTERNAL_UPLOAD','MARKS_REVIEW_CLASS_TEACHER','MESSAGE_SEND','NOTICE_APPROVE','NOTICE_PUBLISH_CLASS_DEPT','NOTICE_PUBLISH_INSTITUTION','NOTICE_PUBLISH_UNIVERSITY','NOTICE_SUBMIT','ONLINE_PERIOD_SET','PERIOD_LOCK','PERIOD_UNLOCK_APPROVE','PERIOD_UNLOCK_REQUEST','PLATFORM_REPORTS_VIEW','POLICY_ACCEPT','POLICY_DRAFT','POLICY_PUBLISH','PRINCIPAL_LEAVE_APPROVE','PRINCIPAL_LEAVE_APPROVER_SET','PROGRAM_RULES_SET','PROMOTION_APPROVE','PROMOTION_RUN','RBAC_MAPPING_CHECK','RECEIPT_CANCEL_APPROVE','REPORTS_VIEW','RESULT_VIEW','RESULT_WITHDRAW_APPROVE','ROLE_ASSIGN','ROLE_ASSIGN_NON_SENSITIVE','ROLE_CUSTOM_MANAGE','SCHOLARSHIP_LIST_APPROVE','SCHOLARSHIP_MANAGE','SELF_SERVICE_VIEW','SENIOR_LEAVE_APPROVE','SMS_EMAIL_SETUP','STAFF_LEAVE_APPLY','STAFF_LEAVE_APPROVE_PRINCIPAL','STAFF_LEAVE_APPROVE_REGISTRAR','STAFF_LEAVE_RECOMMEND_HOD','STAFF_LEAVE_VERIFY_HR','STAFF_RECORD_VIEW','STATUTORY_EXPORT','STRUCTURE_MANAGE','STUDENT_LEAVE_APPLY','STUDENT_LEAVE_APPROVE_CT','STUDENT_LEAVE_APPROVE_HOD','STUDENT_LEAVE_APPROVE_MENTOR','STUDENT_LEAVE_APPROVE_PRINCIPAL','STUDY_MATERIAL_UPLOAD','SUBJECT_ALLOCATE','SYLLABUS_MANAGE','SYLLABUS_VIEW','TALLY_EXPORT','TENANT_OVERSIGHT_VIEW','TENANT_TOP_USERS_CREATE','TERM_LOCK','TERM_UNLOCK','TIMETABLE_BUILD','TIMETABLE_VIEW','UNIVERSITY_POLICY_APPROVE','USAGE_ANALYTICS_VIEW','USER_BULK_UPLOAD','USER_VIEW','VC_LEAVE_APPROVER_SET','WEEKLY_OFF_SET')
           AND support_readable IS DISTINCT FROM true
    ) THEN
        RAISE EXCEPTION 'SUPPORT_READABLE_EXPECTED_ACTION_NOT_ENABLED';
    END IF;
END$$;
